topics/integrating-trig-functions.content:
\begin{align}
&amp;\int \sin x \text{ d}x\\
=&amp; -\cos x + c
\end{align}
\begin{align}
&amp;\int \cos x \text{ d}x\\
=&amp;\ \sin x + c
\end{align}
\begin{align}
&amp;\int \tan x \text{ d}x\\
=&amp;\ \ln|\sec x| + c
\end{align}
\begin{align}
&amp;\int \cot x \text{ d}x\\
=&amp;\ \ln|\sin x| + c 
\end{align}
\begin{align}
&amp;\int \sec x \text{ d}x\\
=&amp;\ \ln|\sec x + \tan x| + c
\end{align}
\begin{align}
&amp;\int \text{cosec } x \text{ d}x\\
=&amp; -\ln|\text{cosec } x + \cot x| + c
\end{align}
